const D = { energy: .6, density: .5, hue: 96, speed: 1, scale: 1, x: .5, y: .5, branch: .5, act: 'cycle', style: 'microscopy', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const BW = Math.max(360, Math.min(1180, Math.round(width * .68)));
const BH = Math.max(200, Math.round(BW * height / width));
const GW = 128, GH = Math.max(48, Math.round(GW * height / width));
const MAXT = 1100;
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- style ground constants (baked grayscale; hue stays live via tint) -----
const st = P.style;
const agarV = st === 'brightfield' ? 84 : st === 'stain' ? 89 : st === 'schematic' ? 25 : 21;
const filV = st === 'brightfield' ? 13 : st === 'stain' ? 18 : st === 'schematic' ? 90 : 97;
const hOff = st === 'brightfield' ? -46 : st === 'stain' ? 118 : st === 'schematic' ? 112 : 0;
const tSat = st === 'brightfield' ? 34 : st === 'stain' ? 50 : st === 'schematic' ? 62 : 52;

if (!S.bio || S.bw !== BW || S.bh !== BH || S.styleUsed !== st || S.seedUsed !== P.seed) {
  if (S.bio && S.bio.remove) S.bio.remove();
  if (S.nug && S.nug.remove) S.nug.remove();
  S.bio = createGraphics(BW, BH); S.bio.pixelDensity(1);
  S.nug = createGraphics(GW, GH); S.nug.pixelDensity(1);
  S.bw = BW; S.bh = BH; S.styleUsed = st; S.seedUsed = P.seed; S.tick = 0; S.cur = 0; S.nodes = [];
  const b = S.bio; b.colorMode(HSB, 360, 100, 100, 100); b.noStroke(); b.background(0, 0, agarV);
  for (let i = 0; i < 260; i++) {
    const x = fr(i * 4 + 1) * BW, y = fr(i * 4 + 2) * BH, r = (12 + fr(i * 4 + 3) * 90) * (BW / 900);
    const dv = (fr(i * 4 + 4) - .5) * (st === 'schematic' ? 5 : 11);
    b.fill(0, 0, Math.max(2, Math.min(98, agarV + dv)), 26);
    b.ellipse(x, y, r * 2, r * 2 * (.7 + fr(i * 7 + 5) * .6));
  }
  if (st === 'schematic') {
    b.stroke(0, 0, agarV + 13, 40); b.strokeWeight(1);
    const gs = BW / 16;
    for (let i = 1; i < 16; i++) { b.line(i * gs, 0, i * gs, BH); b.line(0, i * gs, BW, i * gs); }
    b.noStroke();
  }
  if (st === 'stain') for (let i = 0; i < 26; i++) { b.fill(0, 0, agarV - 22, 4); b.ellipse(BW / 2, BH / 2, BW * (2.5 - i * .05), BH * (2.7 - i * .055)); }
  S.nu = new Float32Array(GW * GH); S.occ = new Float32Array(GW * GH);
  for (let i = 0; i < GW * GH; i++) S.nu[i] = .55 + fr(i * 1.7 + 3) * .45;
  S.tx = new Float32Array(MAXT); S.ty = new Float32Array(MAXT); S.px = new Float32Array(MAXT); S.py = new Float32Array(MAXT);
  S.td = new Float32Array(MAXT); S.ta = new Float32Array(MAXT); S.tw = new Float32Array(MAXT); S.al = new Uint8Array(MAXT);
}

const bio = S.bio, nug = S.nug, nu = S.nu, occ = S.occ;
const tx = S.tx, ty = S.ty, ppx = S.px, ppy = S.py, td = S.td, ta = S.ta, tw = S.tw, al = S.al;
S.tick = (S.tick || 0) + 1;
const rnd = k => { const s = Math.sin(k * 12.9898 + S.tick * .6180339 + P.seed * 7.13) * 43758.5453; return s - Math.floor(s); };
const U = BW / 900;

// ---- act: multi-minute medium richness (boom / bust) -----------------------
let rich;
if (P.act === 'colonise') rich = 1.9;
else if (P.act === 'starve') rich = .32;
else rich = .45 + 1.4 * (.5 + .5 * Math.sin(K.t * .0129 + .8 * Math.sin(K.t * .0043 + 1.7)));

// ---- autolysis: old biomass fades back into the medium ---------------------
if (S.tick % 30 === 0) { bio.noStroke(); bio.fill(0, 0, agarV, 1.05 + P.speed * .5); bio.rect(0, 0, BW, BH); }

// ---- growth constants ------------------------------------------------------
const target = Math.round(90 + P.density * 470);
const SP = (.22 + P.energy * .62) * (.45 + P.speed * .75) * U;
const SDb = (8 + P.scale * 10) * U;
const SDx = SDb / BW * GW, SDy = SDb / BH * GH;
const SA = .62;
const brP = (.0016 + P.branch * .011) * (.4 + P.speed * .8);
const wetG = .5 + .5 * Math.sin(K.t * .083 + .6 * Math.sin(K.t * .0291 + .5));
const clampG = (gx, gy, f) => {
  let ix = Math.floor(gx), iy = Math.floor(gy);
  if (ix < 0) ix = 0; if (iy < 0) iy = 0; if (ix >= GW) ix = GW - 1; if (iy >= GH) iy = GH - 1;
  return f[iy * GW + ix];
};
const spawn = (x, y, d, w) => {
  for (let n = 0; n < MAXT; n++) {
    S.cur = (S.cur + 1) % MAXT;
    if (!al[S.cur]) { const k = S.cur; al[k] = 1; tx[k] = x; ty[k] = y; ppx[k] = x; ppy[k] = y; td[k] = d; ta[k] = 0; tw[k] = w; return true; }
  }
  return false;
};

bio.strokeCap(ROUND);
let alive = 0;
for (let k = 0; k < MAXT; k++) {
  if (!al[k]) continue;
  alive++;
  const gx = tx[k] / BW * GW, gy = ty[k] / BH * GH, d = td[k];
  const c = clampG(gx + Math.cos(d) * SDx, gy + Math.sin(d) * SDy, nu);
  const l = clampG(gx + Math.cos(d - SA) * SDx, gy + Math.sin(d - SA) * SDy, nu);
  const r = clampG(gx + Math.cos(d + SA) * SDx, gy + Math.sin(d + SA) * SDy, nu);
  let nd = d;
  const turn = .05 + P.energy * .075;
  if (l > c && l >= r) nd -= turn; else if (r > c && r > l) nd += turn;
  nd += (rnd(k * 3 + 1) - .5) * (.05 + (1 - P.energy) * .11);
  td[k] = nd;
  const nx = tx[k] + Math.cos(nd) * SP, ny = ty[k] + Math.sin(nd) * SP;
  if (nx < 5 || nx > BW - 5 || ny < 5 || ny > BH - 5) {
    td[k] = Math.atan2(BH * .5 - ty[k], BW * .5 - tx[k]) + (rnd(k * 5 + 9) - .5) * .9;
    ta[k] += 5; if (ta[k] > 3400) al[k] = 0;
    continue;
  }
  const ngx = nx / BW * GW, ngy = ny / BH * GH;
  const gi = Math.min(GH - 1, Math.max(0, Math.floor(ngy))) * GW + Math.min(GW - 1, Math.max(0, Math.floor(ngx)));
  // anastomosis: a mature tip meeting OTHER established mycelium ahead fuses.
  // sampling 2+ cells forward keeps a tip from fusing with its own fresh trail.
  if (ta[k] > 60 && clampG(ngx + Math.cos(nd) * 2.3, ngy + Math.sin(nd) * 2.3, occ) > 3.2) {
    al[k] = 0;
    if (S.nodes.length < 90) S.nodes.push([nx, ny, tw[k]]);
    bio.stroke(0, 0, filV, 100); bio.strokeWeight(Math.max(.7, tw[k] * U)); bio.line(ppx[k], ppy[k], nx, ny);
    continue;
  }
  if (nu[gi] < .07) { ta[k] += 7; if (ta[k] > 3400) { al[k] = 0; continue; } }
  nu[gi] -= (.0026 + P.energy * .0042) * (.4 + P.speed * .7);
  if (nu[gi] < 0) nu[gi] = 0;
  occ[gi] += .35;
  const ww = Math.max(.65, tw[k] * U * (st === 'schematic' ? .8 : 1));
  bio.strokeWeight(ww);
  bio.stroke(0, 0, filV, st === 'microscopy' ? 74 : 82);
  bio.line(ppx[k], ppy[k], nx, ny);
  if (st === 'stain' && Math.floor(ta[k]) % 41 === 0) { bio.strokeWeight(ww * 2.1); bio.stroke(0, 0, filV - 6, 55); bio.point(nx, ny); }
  ppx[k] = nx; ppy[k] = ny; tx[k] = nx; ty[k] = ny; ta[k]++;
  if (alive < MAXT - 12 && ta[k] > 24 && rnd(k * 9 + 3) < brP * (.25 + nu[gi]) * rich) {
    const side = rnd(k * 11 + 5) > .5 ? 1 : -1;
    spawn(nx, ny, nd + side * (.5 + rnd(k * 13 + 7) * .75), Math.max(.55, tw[k] * .78));
  }
  if (ta[k] > 5200) al[k] = 0;
}

// ---- re-inoculation into the richest unclaimed medium ---------------------
if (alive < target) {
  const want = Math.min(6, target - alive);
  for (let s = 0; s < want; s++) {
    let bx = GW * .5, by = GH * .5, best = -1e9;
    for (let q = 0; q < 7; q++) {
      const cx = rnd(s * 31 + q * 3 + 1) * GW, cy = rnd(s * 31 + q * 3 + 2) * GH;
      const v = clampG(cx, cy, nu) - clampG(cx, cy, occ) * .16
        - Math.hypot(cx / GW - P.x, cy / GH - P.y) * .6;      // inoculum drawn toward the anchor
      if (v > best) { best = v; bx = cx; by = cy; }
    }
    const a0 = rnd(s * 41 + 7) * 6.283;
    for (let q = 0; q < 3; q++) spawn(bx / GW * BW, by / GH * BH, a0 + q * 2.094, 1.5 + P.scale * .9);
  }
}

// ---- nutrient regrowth + network memory decay ------------------------------
const regen = (.00012 + .00046 * rich) * (.4 + P.speed * .8);
for (let i = 0; i < GW * GH; i++) { const v = nu[i]; nu[i] = v + regen * (1 - v); occ[i] *= .9993; }

// ---- fusion knots ----------------------------------------------------------
if (S.nodes.length) {
  for (let i = S.nodes.length - 1; i >= 0; i--) {
    const q = S.nodes[i];
    if (st === 'schematic') { bio.noFill(); bio.stroke(0, 0, filV, 70); bio.strokeWeight(1); bio.ellipse(q[0], q[1], 7 * U, 7 * U); }
    else { bio.noStroke(); bio.fill(0, 0, filV, st === 'microscopy' ? 90 : 78); bio.ellipse(q[0], q[1], q[2] * 2.4 * U, q[2] * 2.4 * U); }
    S.nodes.splice(i, 1);
  }
}

// ---- depletion / exudate wash ---------------------------------------------
nug.loadPixels(); const np = nug.pixels;
const wash = 40 + P.density * 52;
for (let i = 0; i < GW * GH; i++) {
  const v = 255 - (1 - Math.min(1, nu[i])) * wash;
  const o = 4 * i; np[o] = v; np[o + 1] = v * (st === 'brightfield' ? .985 : 1); np[o + 2] = v * .97; np[o + 3] = 255;
}
nug.updatePixels();

// ---- composite -------------------------------------------------------------
const expo = 62 + P.energy * 30 + K.intensity * 8 + A.rms * 20 + wetG * 9;
push();
tint(P.hue + hOff, tSat, Math.min(100, expo + 22), P.alpha);
image(bio, 0, 0, width, height);
blendMode(MULTIPLY);
tint(0, 0, 100, P.alpha);
image(nug, 0, 0, width, height);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
